def method(s,signature):
 start=s.index('    '+signature);brace=s.index('{',start);depth=1;i=brace+1
 while depth:
  depth+=(s[i]=='{')-(s[i]=='}');i+=1
 return s[start:i]+'\n'

def make_header(kind):
 base=(p/(kind+'_baseline.hpp')).read_text();candidate=(p/('classic_delsuffix.hpp'if kind=='classic'else'compressed_prefixdelete.hpp')).read_text();extras='\nprivate:\n'
 if kind=='compressed':
  for suffix,body in [('control',base),('candidate',candidate)]:
   extras+=method(body,'Index leaf_for(U key) const noexcept').replace('leaf_for(', 'leaf_for_'+suffix+'(')
   extras+=method(body,'Index find_leaf(U key) const noexcept').replace('find_leaf(', 'find_leaf_'+suffix+'(').replace('leaf_for(', 'leaf_for_'+suffix+'(')
